const postgres = Postgres.main;
const yesterday = new Date(Date.now() - 86400000);
const s = (await postgres.query(`SELECT (SELECT COUNT(*) FROM organizations) as orgs, (SELECT COUNT(*) FROM users WHERE last_login>=$1) as active_users, (SELECT COUNT(*) FROM portfolios) as portfolios, (SELECT COALESCE(SUM(market_value),0) FROM debt_instruments) as aum, (SELECT COUNT(*) FROM workflows.workflow_executions WHERE created_at>=$1 AND status='success') as ok, (SELECT COUNT(*) FROM workflows.workflow_executions WHERE created_at>=$1 AND status='error') as fail`, [yesterday.toISOString()])).rows[0];
const total = parseInt(s.ok||0)+parseInt(s.fail||0);
const rate = total > 0 ? ((parseInt(s.ok||0)/total)*100).toFixed(1) : 0;
return [{ json: { channel: '#daily-digest', severity: 'low', dedupeKey: `digest_${new Date().toISOString().split('T')[0]}`, text: `📊 *Daily Digest*
• Orgs: ${s.orgs} | Users (24h): ${s.active_users} | Portfolios: ${s.portfolios}
• AUM: $${parseFloat(s.aum||0).toLocaleString()}
• Workflows: ${s.ok} ok, ${s.fail} fail (${rate}%)`, metadata: { flow: 'daily_digest' } } }];

const postgres = Postgres.main;
const w = new Date(Date.now()-7*86400000);
const mrr = (await postgres.query(`SELECT COALESCE(SUM(amount),0) as t FROM mrr_events WHERE event_type!='cancellation' AND customer_id NOT IN (SELECT customer_id FROM mrr_events WHERE event_type='cancellation')`)).rows[0].t;
const nb = (await postgres.query(`SELECT COUNT(*) as c, COALESCE(SUM(amount),0) as m FROM mrr_events WHERE event_type='subscription.created' AND created_at>=$1`, [w.toISOString()])).rows[0];
const ch = (await postgres.query(`SELECT COUNT(*) as c, COALESCE(SUM(amount),0) as m FROM mrr_events WHERE event_type='cancellation' AND created_at>=$1`, [w.toISOString()])).rows[0];
const net = parseFloat(nb.m||0)-parseFloat(ch.m||0);
return [{ json: { channel: '#weekly-report', severity: 'low', dedupeKey: `weekly_${new Date().toISOString().split('T')[0]}`, text: `📈 *Weekly Report*
*MRR:* $${parseFloat(mrr||0).toLocaleString()}
*New:* ${nb.c} ($${parseFloat(nb.m||0).toLocaleString()}) | *Lost:* ${ch.c} ($${parseFloat(ch.m||0).toLocaleString()}) | *Net:* $${net.toLocaleString()}`, metadata: { flow: 'weekly_report', mrr } } }];

const postgres = Postgres.main;
const r = await postgres.query(`SELECT id, subject, priority, EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - created_at))/60 as age_min FROM support_tickets WHERE status IN ('open','in_progress') AND ((priority='urgent' AND EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP-created_at))/60>15) OR (priority='high' AND EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP-created_at))/60>60) OR (priority='medium' AND EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP-created_at))/60>240) OR (priority='low' AND EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP-created_at))/60>1440)) ORDER BY created_at ASC LIMIT 20`);
if (r.rows.length === 0) return [];
const lines = r.rows.map(t => `• [${t.priority.toUpperCase()}] #${t.id}: ${t.subject} — ${Math.floor(t.age_min)}m`);
return [{ json: { channel: '#support-alerts', severity: 'high', dedupeKey: `sla_breach_${Date.now()}`, text: `🚨 *SLA Breach: ${r.rows.length} tickets*
${lines.join('\n')}`, metadata: { flow: 'sla_alert', count: r.rows.length } } }];

const postgres = Postgres.main;
const h = new Date(Date.now()-3600000);
const la = (await postgres.query(`SELECT COUNT(*) as total, COUNT(CASE WHEN success=false THEN 1 END) as failed FROM login_attempts WHERE created_at>=$1`, [h.toISOString()])).rows[0];
const aa = (await postgres.query(`SELECT ip_address, COUNT(*) as c FROM api_access_logs WHERE created_at>=$1 GROUP BY ip_address HAVING COUNT(*)>1000`, [h.toISOString()]));
const failRate = parseInt(la.total||0) > 0 ? ((parseInt(la.failed||0)/parseInt(la.total||0))*100).toFixed(1) : 0;
const alerts = [];
if (parseFloat(failRate) > 30) alerts.push(`⚠️ Login failure rate: ${failRate}%`);
if (aa.rows.length > 0) alerts.push(`⚠️ ${aa.rows.length} IPs exceeded rate limits`);
if (alerts.length === 0) return [];
return [{ json: { channel: '#security-alerts', severity: 'high', dedupeKey: `security_${Date.now()}`, text: `🔒 *Security Alert*
${alerts.join('\n')}`, metadata: { flow: 'security_alert' } } }];

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const ts = new Date().toISOString().replace(/[:.]/g,'-');
const dir = `/var/backups/quantive/${ts}`;
let result;
try {
  fs.mkdirSync(dir, { recursive: true });
  const f = path.join(dir, 'quantive.dump');
  execSync(`pg_dump -h ${process.env.DB_HOST||'localhost'} -U ${process.env.DB_USER||'quantive'} -d ${process.env.DB_NAME||'quantive'} -Fc -f ${f}`, { timeout: 300000 });
  const sz = (fs.statSync(f).size/(1024*1024)).toFixed(2);
  await Postgres.main.query(`INSERT INTO workflows.backup_history (backup_path,backup_size,status,created_at) VALUES ($1,$2,'completed',CURRENT_TIMESTAMP)`, [dir, `${sz}MB`]);
  result = { success: true, channel: '#ops-notifications', severity: 'low', dedupeKey: `backup_${ts}`, text: `✅ *Backup Complete*
*Path:* ${dir}
*Size:* ${sz}MB`, metadata: { flow: 'backup', size: sz } };
} catch (e) {
  result = { success: false, channel: '#ops-notifications', severity: 'high', dedupeKey: `backup_fail_${ts}`, text: `❌ *Backup Failed*
*Error:* ${e.message}`, metadata: { flow: 'backup', error: e.message } };
}
return [{ json: result }];

const postgres = Postgres.main;
const h = new Date(Date.now()-3600000);
const r = await postgres.query(`SELECT error_type, message, severity, COUNT(*) as count FROM workflows.workflow_errors WHERE created_at>=$1 GROUP BY error_type, message, severity ORDER BY count DESC LIMIT 10`, [h.toISOString()]);
if (r.rows.length === 0) return [];
const lines = r.rows.map(e => `• [${e.severity}] ${e.error_type}: ${(e.message||'').substring(0,50)} (×${e.count})`);
const highCount = r.rows.filter(e => e.severity === 'critical' || e.severity === 'high').reduce((s,e) => s + parseInt(e.count), 0);
return [{ json: { channel: '#platform-alerts', severity: highCount > 5 ? 'critical' : 'high', dedupeKey: `errors_${Date.now()}`, text: `⚠️ *Recent Errors (${r.rows.length} types)*
${lines.join('\n')}`, metadata: { flow: 'error_monitor', errorCount: r.rows.length } } }];

const crypto = require('crypto');
const item = $input.first().json;
const body = item.body || {};
const sig = (item.headers && item.headers['x-quantive-signature']) || '';
const secret = process.env.WEBHOOK_SECRET || '';
const payload = JSON.stringify(body);
const expected = crypto.createHmac('sha256', secret).update(payload).digest('hex');
let valid = false;
try {
  const a = Buffer.from(sig, 'hex');
  const b = Buffer.from(expected, 'hex');
  valid = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) { valid = false; }
if (!valid) {
  try {
    await Postgres.main.query(`INSERT INTO workflows.workflow_errors (workflow_id, workflow_name, execution_id, error_type, message, node_id, node_type, severity, created_at) VALUES ('wf4-operations-internal','WF-4: Operations & Internal',$1,'webhook.auth','Invalid HMAC on /support-ticket','Verify Support HMAC','webhook','high',CURRENT_TIMESTAMP)`, [$execution.id]);
  } catch (e) {}
  return [];
}
return [item];

const ticket = $input.first().json.body;
if (!ticket || !ticket.subject) throw new Error('Ticket missing subject');
const postgres = Postgres.main;
const r = await postgres.query(`INSERT INTO support_tickets (subject,description,priority,status,customer_email,created_at) VALUES ($1,$2,$3,'open',$4,CURRENT_TIMESTAMP) RETURNING id`, [ticket.subject, ticket.description, ticket.priority||'medium', ticket.email]);
const isUrgent = (ticket.priority||'medium') === 'urgent';
return [{ json: { ticketId: r.rows[0].id, channel: '#support-alerts', severity: isUrgent ? 'critical' : 'low', dedupeKey: `ticket_${r.rows[0].id}`, text: isUrgent ? `🚨 *URGENT TICKET #${r.rows[0].id}*
*Subject:* ${ticket.subject}
*Email:* ${ticket.email}` : `🎫 *Ticket #${r.rows[0].id}*
*Subject:* ${ticket.subject}`, metadata: { flow: 'support_ticket', ticketId: r.rows[0].id } } }];
